package com.vandorlabs.neoforge.screen;


import net.minecraft.nbt.*;
/** Actual installed development transmitter wrappers upgraded into row and main settings. */
public final class ScreenTransmissionChecks {
 public static void main(String[] args)throws Exception{java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;for(String slot:new String[]{"main","row_0_0","row_1_1","row_9_0","row_bad"})for(int count=0;count<2;count++)for(int damage:new int[]{-1,0,1,2,3,4,32767})for(int existing=0;existing<3;existing++){CompoundTag input=input(slot,count,damage,existing),before=input.copy(),normalized=NativeScreenTransmissionMigration.read(input).referenceProjection();if(!input.equals(before))throw new AssertionError("Source normalization mutated input");hash.update(canonical(normalized).getBytes("UTF-8"));cases++;}CompoundTag opaque=input("main",1,0,0);CompoundTag caps=new CompoundTag();caps.putString("External","opaque");opaque.getCompound("ForgeData").getCompound("VandorTransmitters").getCompound("main").put("ForgeCaps",caps);CompoundTag original=opaque.copy();var guarded=NativeScreenTransmissionMigration.read(opaque);opaque.remove("ForgeData");if(guarded.installable()||!guarded.unchanged().equals(original))throw new AssertionError("Opaque module ownership lost");try{guarded.install();throw new AssertionError("Unsupported module activated");}catch(IllegalStateException expected){}if(NativeScreenTransmissionMigration.read(input("cockpit_future",1,0,0)).installable())throw new AssertionError("Deferred cockpit behavior installed");StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("ffdca89a78e6b2eb8ca88cd54303b15fdd99e3e22b89b58266f3691ee0016ab5"))throw new AssertionError("Native differs from actual legacy transmission "+out);System.out.println("Native Screen transmission parity PASS cases="+cases+" sha256="+out);}
 public static CompoundTag input(String slot,int count,int damage,int existing){CompoundTag root=new CompoundTag(),forge=new CompoundTag(),modules=new CompoundTag(),item=new CompoundTag(),settings=new CompoundTag();item.putString("id","vandorlabs:redstone_transmitter");item.putByte("Count",(byte)count);item.putShort("Damage",(short)damage);CompoundTag itemTag=new CompoundTag();itemTag.putIntArray("RedstoneChannels",new int[]{31,32});item.put("tag",itemTag);modules.put(slot,item);forge.put("VandorTransmitters",modules);forge.putString("VandorSharedScreenTransmitter","old");forge.putString("ForeignForge","retain");if(existing!=0){CompoundTag main=new CompoundTag();main.putIntArray("Channels",existing==1?new int[]{55}:new int[]{-1});settings.put("main",main);forge.put("VandorTransmission",settings);}root.put("ForgeData",forge);root.putInt("TransmitterSchema",1);root.putString("ForeignRoot","retain");for(String side:new String[]{"RedstonePrimary","RedstoneSecondary"}){CompoundTag controls=new CompoundTag();ListTag rows=new ListTag();for(int i=0;i<2;i++){CompoundTag row=new CompoundTag();row.putString("Label","row"+i);if(existing!=0)row.putIntArray("RedstoneChannels",existing==1?new int[]{55}:new int[]{-1});rows.add(row);}controls.put("Rows",rows);root.put(side,controls);}return root;}
 private static String canonical(Tag tag){if(tag instanceof CompoundTag){CompoundTag compound=(CompoundTag)tag;StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(compound.getAllKeys()))out.append(key).append(':').append(canonical(compound.get(key))).append(';');return out.append('}').toString();}if(tag instanceof ListTag){ListTag list=(ListTag)tag;StringBuilder out=new StringBuilder("[");for(int i=0;i<list.size();i++)out.append(canonical(list.get(i))).append(';');return out.append(']').toString();}return tag.toString();}
}
